    public Object parseLedgerEntry(Map<String, Object> item, Map<String, Object> currency)
    {
        //
        //     {
        //         "id": 234467,
        //         "user_id": 1,
        //         "coin": "BTC",
        //         "wallet_id": 27913,
        //         "type": "Realized P&L",
        //         "amount": "-0.00000006",
        //         "tx_id": "",
        //         "address": "BTCUSD",
        //         "wallet_balance": "0.03000330",
        //         "exec_time": "2019-12-09T00:00:25.000Z",
        //         "cross_seq": 0
        //     }
        //
        //     {
        //         "symbol": "XRPUSDT",
        //         "side": "Buy",
        //         "funding": "",
        //         "orderLinkId": "linear-order",
        //         "orderId": "592b7e41-78fd-42e2-9aa3-91e1835ef3e1",
        //         "fee": "0.00260280",
        //         "change": "-0.0026028",
        //         "cashFlow": "0",
        //         "transactionTime": "1672121182224",
        //         "type": "TRADE",
        //         "feeRate": "0.0006",
        //         "size": "12",
        //         "qty": "12",
        //         "cashBalance": "5086.58101322",
        //         "currency": "USDT",
        //         "category": "linear",
        //         "tradePrice": "0.3615",
        //         "tradeId": "8569c10f-5061-5891-81c4-a54929847eb3"
        //     }
        //
        String currencyId = this.safeString2(item, "coin", "currency");
        String code = this.safeCurrencyCode(currencyId, currency);
        Map<String, Object> currencyResolved = (Map<String, Object>) this.safeCurrency(currencyId, currency);
        String amountString = this.safeString2(item, "amount", "change");
        String afterString = this.safeString2(item, "wallet_balance", "cashBalance");
        String direction = "in";
        if (Precise.stringLt(amountString, "0"))
        {
            direction = "out";
        }
        Object before = null;
        Object after = null;
        Object amount = null;
        if (!java.util.Objects.equals(afterString, null) && !java.util.Objects.equals(amountString, null))
        {
            String difference = null;
            if (java.util.Objects.equals(direction, "out"))
            {
                difference = amountString;
            } else
            {
                difference = Precise.stringNeg(amountString);
            }
            before = this.parseToNumeric(Precise.stringAdd(afterString, difference));
            after = this.parseToNumeric(afterString);
            amount = this.parseToNumeric(Precise.stringAbs(amountString));
        }
        Long timestamp = this.parse8601(this.safeString(item, "exec_time"));
        if (java.util.Objects.equals(timestamp, null))
        {
            timestamp = (Long) this.safeInteger(item, "transactionTime");
        }
        return this.safeLedgerEntry(Helpers.newMap(
            "info", item,
            "id", this.safeString(item, "id"),
            "direction", direction,
            "account", this.safeString(item, "wallet_id"),
            "referenceId", this.safeString(item, "tx_id"),
            "referenceAccount", null,
            "type", this.parseLedgerEntryType(this.safeString(item, "type")),
            "currency", code,
            "amount", amount,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "before", before,
            "after", after,
            "status", "ok",
            "fee", new HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", Bybit.this.safeNumber(item, "fee", (Object) null) );
            }}
        ), currencyResolved);
    }

    public Object parseLedgerEntryType(String type)
    {
        Map<String, Object> types = new HashMap<String, Object>() {{
            put( "Deposit", "transaction" );
            put( "Withdraw", "transaction" );
            put( "RealisedPNL", "trade" );
            put( "Commission", "fee" );
            put( "Refund", "cashback" );
            put( "Prize", "prize" );
            put( "ExchangeOrderWithdraw", "transaction" );
            put( "ExchangeOrderDeposit", "transaction" );
            put( "TRANSFER_IN", "transaction" );
            put( "TRANSFER_OUT", "transaction" );
            put( "TRADE", "trade" );
            put( "SETTLEMENT", "trade" );
            put( "DELIVERY", "trade" );
            put( "LIQUIDATION", "trade" );
            put( "BONUS", "Prize" );
            put( "FEE_REFUND", "cashback" );
            put( "INTEREST", "transaction" );
            put( "CURRENCY_BUY", "trade" );
            put( "CURRENCY_SELL", "trade" );
        }};
        return this.safeString(types, ((String)type), type);
    }

    /**
     * @method
     * @name bybit#withdraw
     * @description make a withdrawal
     * @see https://bybit-exchange.github.io/docs/v5/asset/withdraw
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {string} tag
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.accountType] 'UTA', 'FUND', 'FUND,UTA', and 'SPOT (for classic accounts only)
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public CompletableFuture<Transaction> withdraw(String code, Object amount, String address, String tag, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            List<Object> tagWithdrawTagparamsWithdrawTagVariable = (List<Object>) this.handleWithdrawTagAndParams(tag, parameters);
            var tagWithdrawTag = ((List<Object>) tagWithdrawTagparamsWithdrawTagVariable).get(0);
            Map<String, Object> paramsWithdrawTag = (Map<String, Object>) ((List<Object>) tagWithdrawTagparamsWithdrawTagVariable).get(1);
            Object accounts = (this.isUnifiedEnabled(new HashMap<String, Object>() {{}})).join();
            Object isUta = (accounts == null || 1 >= ((List<?>)accounts).size() ? null : ((List<?>)accounts).get(1));
            List<Object> accountTypeOptionparamsAccountTypeVariable = (List<Object>) this.handleOptionStringAndParams(paramsWithdrawTag, "withdraw", "accountType", (String) null);
            String accountTypeOption = (String) ((List<Object>) accountTypeOptionparamsAccountTypeVariable).get(0);
            var paramsAccountType = ((List<Object>) accountTypeOptionparamsAccountTypeVariable).get(1);
            String defaultAccountType = (((java.util.Objects.equals(isUta, true)))) ? "UTA" : "SPOT";
            String accountType = (((java.util.Objects.equals(accountTypeOption, null)))) ? defaultAccountType : accountTypeOption;
            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            this.checkAddress(address);
            Map<String, Object> currency = (Map<String, Object>) this.currency((String) (code));
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "coin", ((Map<String, Object>)currency).get("id") );
                put( "amount", Bybit.this.numberToString(amount) );
                put( "address", address );
                put( "timestamp", Bybit.this.milliseconds() );
                put( "accountType", accountType );
            }};
            if (!java.util.Objects.equals(tagWithdrawTag, null))
            {
                request.put("tag", tagWithdrawTag);
            }
            List<Object> networkCodequeryVariable = (List<Object>) this.handleNetworkCodeAndParams(paramsAccountType);
            String networkCode = (String) ((List<Object>) networkCodequeryVariable).get(0);
            var query = ((List<Object>) networkCodequeryVariable).get(1);
            Object networkId = this.networkCodeToId(networkCode, code);
            if (!java.util.Objects.equals(networkId, null))
            {
                request.put("chain", ((String)networkId).toUpperCase());
            }
            Map<String, Object> response = (this.privatePostV5AssetWithdrawCreate(this.extend(request, query))).join();
            //
            //    {
            //         "retCode": "0",
            //         "retMsg": "success",
            //         "result": {
            //             "id": "9377266"
            //         },
            //         "retExtInfo": {},
            //         "time": "1666892894902"
            //     }
            //
            Map<String, Object> result = (Map<String, Object>) this.safeDict(response, "result", new HashMap<String, Object>() {{}});
            return this.parseTransaction((Map<String, Object>) (result), currency);
        }).thenApply(Transaction::new);

    }

